/* Tiny fp32 RVV bench: verifies zve32f-class vector float on the engine. */
#include <andesim/ROI.h>
#include <riscv_vector.h>
#include <stdint.h>
#include <stdio.h>

#define N 256
static float a[N], b[N], c[N];

static __attribute__((noinline)) void saxpy(void)
{
  for (size_t i = 0; i < N;) {
    size_t vl = __riscv_vsetvl_e32m1(N - i);
    vfloat32m1_t va = __riscv_vle32_v_f32m1(&a[i], vl);
    vfloat32m1_t vb = __riscv_vle32_v_f32m1(&b[i], vl);
    vfloat32m1_t vc = __riscv_vfmacc_vf_f32m1(vb, 2.0f, va, vl);
    __riscv_vse32_v_f32m1(&c[i], vc, vl);
    i += vl;
  }
}

int main(void)
{
  for (int i = 0; i < N; i++) { a[i] = (float) i; b[i] = 1.0f; }

  andesim_ROI_begin();
  saxpy();
  uint64_t c0, c1;
  __asm__ __volatile__("csrr %0, mcycle" : "=r"(c0));
  saxpy();
  __asm__ __volatile__("csrr %0, mcycle" : "=r"(c1));
  /* print INSIDE the ROI: nothing executes after ROI end in hybrid mode */
  printf("check c[100]=%f inner_mcycle_delta=%lu\n", (double) c[100],
         (unsigned long) (c1 - c0));
  andesim_ROI_end();
  return 0;
}

