/* Probe which vector ops trap on the engine. Prints a marker before each
 * op; the first trap kills the run and the handler prints mepc. */
#include <stdio.h>
#include <stdint.h>

static float fa[16] = {1, 2, 3, 4}, fb[16] = {5, 6, 7, 8}, fc[16];
static int32_t ia[16] = {1, 2, 3, 4}, ib[16] = {5, 6, 7, 8}, ic[16];

int main(void)
{
  unsigned long frm;
  __asm__ __volatile__("csrr %0, frm" : "=r"(frm));
  printf("frm=%lu\n", frm);
  __asm__ __volatile__("csrwi frm, 0"); /* rule out invalid-frm trap */

  printf("1 vadd.vv i32\n");
  __asm__ __volatile__(
      "vsetivli x0, 4, e32, m1, ta, ma\n"
      "vle32.v v1, (%0)\n"
      "vle32.v v2, (%1)\n"
      "vadd.vv v3, v1, v2\n"
      "vse32.v v3, (%2)\n" ::"r"(ia), "r"(ib), "r"(ic)
      : "memory");

  printf("2 vfadd.vv f32\n");
  __asm__ __volatile__(
      "vle32.v v1, (%0)\n"
      "vle32.v v2, (%1)\n"
      "vfadd.vv v3, v1, v2\n"
      "vse32.v v3, (%2)\n" ::"r"(fa), "r"(fb), "r"(fc)
      : "memory");

  printf("3 vfmacc.vv f32\n");
  __asm__ __volatile__(
      "vle32.v v1, (%0)\n"
      "vle32.v v2, (%1)\n"
      "vle32.v v3, (%2)\n"
      "vfmacc.vv v3, v1, v2\n"
      "vse32.v v3, (%2)\n" ::"r"(fa), "r"(fb), "r"(fc)
      : "memory");

  printf("4 vfmul.vf f32\n");
  __asm__ __volatile__(
      "vle32.v v1, (%0)\n"
      "flw fa5, 0(%1)\n"
      "vfmul.vf v3, v1, fa5\n"
      "vse32.v v3, (%2)\n" ::"r"(fa), "r"(fb), "r"(fc), "r"(fc)
      : "memory");

  printf("5 vfcvt.f.x.v\n");
  __asm__ __volatile__(
      "vle32.v v1, (%0)\n"
      "vfcvt.f.x.v v2, v1\n"
      "vse32.v v2, (%1)\n" ::"r"(ia), "r"(fc)
      : "memory");

  printf("all ok, fc[0]=%f\n", (double) fc[0]);
  return 0;
}

