/* Integer RVV bench + in-ROI mcycle/rdcycle readback on the vsim leg. */
#include <andesim/ROI.h>
#include <riscv_vector.h>
#include <stdint.h>
#include <stdio.h>

#define N 256
static int32_t a[N], b[N], c[N];

static __attribute__((noinline)) void vaddk(void)
{
  for (size_t i = 0; i < N;) {
    size_t vl = __riscv_vsetvl_e32m1(N - i);
    vint32m1_t va = __riscv_vle32_v_i32m1(&a[i], vl);
    vint32m1_t vb = __riscv_vle32_v_i32m1(&b[i], vl);
    __riscv_vse32_v_i32m1(&c[i], __riscv_vadd_vv_i32m1(va, vb, vl), vl);
    i += vl;
  }
}

int main(void)
{
  for (int i = 0; i < N; i++) { a[i] = i; b[i] = 2 * i; }

  andesim_ROI_begin();
  uint64_t m0, m1, r0, r1;
  __asm__ __volatile__("csrr %0, mcycle" : "=r"(m0));
  __asm__ __volatile__("rdcycle %0" : "=r"(r0));
  vaddk();
  __asm__ __volatile__("csrr %0, mcycle" : "=r"(m1));
  __asm__ __volatile__("rdcycle %0" : "=r"(r1));
  printf("c[100]=%d mcycle_delta=%lu rdcycle_delta=%lu\n", (int) c[100],
         (unsigned long) (m1 - m0), (unsigned long) (r1 - r0));
  andesim_ROI_end();
  return 0;
}

